def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')
    my_d = n - my_c
    last_me = me[-1]
    last_opp = opp[-1]

    # Consecutive opponent defections
    run_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            run_d += 1
        else:
            break

    # Consecutive opponent cooperations
    run_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            run_c += 1
        else:
            break

    opp_rate = opp_c / float(n)
    remaining = 100 - n

    # ---- Endgame: defect in final rounds against cooperative opponents ----
    if remaining <= 1:
        if opp_rate >= 0.35:
            return 'D'
        return 'D'

    if remaining <= 3:
        # last chances to grab points from cooperators
        if opp_rate >= 0.5:
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'D'

    # ---- Hardcore defector detection ----
    if n >= 6:
        last6d = sum(1 for a in opp[-6:] if a == 'D')
        if last6d >= 6:
            # Near-always-defector: defect, rare probe
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        if last6d == 0:
            return 'C'

    if opp_d == 0:
        # Never defected: cooperate fully (avoid pointless probes)
        return 'C'

    if opp_c == 0:
        # Always defected: defect almost always
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # ---- Opponent defecting heavily ----
    if opp_rate < 0.25:
        if last_opp == 'D':
            return 'D'
        # opponent just cooperated; exploit with some probability
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # ---- Run of defections ----
    if run_d >= 3:
        # strong punishment, but don't lock forever
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    if run_d == 2:
        # two in a row: retaliate, then will forgive after
        return 'D'

    # ---- Last move analysis ----
    if last_opp == 'D':
        # single recent defection
        if last_me == 'C':
            # we cooperated and got burned: punish with high probability
            recent_d = sum(1 for a in opp[-5:] if a == 'D')
            if recent_d >= 2:
                return 'D'
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        else:
            # we already defected; try to restore cooperation
            if run_c >= 1:
                return 'C'
            return 'C' if rng.random() < 0.6 else 'D'

    # Opponent cooperated last
    if last_me == 'D':
        # reward cooperation by returning to C
        return 'C'

    # Both cooperating
    # Check for streaks of mutual cooperation and exploit if opponent seems naive
    if n >= 4:
        if opp[-1] == 'C' and opp[-2] == 'C' and opp[-3] == 'C':
            # long cooperative streak; occasionally test
            if rng.random() < 0.04:
                return 'D'
            return 'C'

    # Cooperative streak ends before now?
    if run_c >= 4 and opp_rate > 0.7:
        # mostly cooperative; rare probe to test
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # Default: cooperate
    return 'C'
